export type ReserveResult =
  | { status: "reserved"; reservationId: string; sku: string; quantity: number }
  | { status: "insufficient"; sku: string; available: number }
  | { status: "unknown_sku"; sku: string };

export interface InventoryStore {
  reserve(sku: string, quantity: number, orderRef: string): Promise<ReserveResult>;
  release(reservationId: string): Promise<void>;
}

export class InsufficientStockError extends Error {
  constructor(public readonly sku: string, public readonly available: number) {
    super(`insufficient stock for ${sku}: ${available} available`);
    this.name = "InsufficientStockError";
  }
}

import { InventoryStore, InsufficientStockError, ReserveResult } from "./inventory";

export interface OrderLine {
  sku: string;
  quantity: number;
  unitPriceCents: number;
}

export interface OrderRepository {
  insert(order: {
    ref: string;
    customerId: string;
    lines: OrderLine[];
    reservationIds: string[];
    totalCents: number;
  }): Promise<void>;
}

export class OrderPlacementService {
  constructor(
    private readonly inventory: InventoryStore,
    private readonly orders: OrderRepository,
    private readonly newRef: () => string,
  ) {}

  async placeOrder(customerId: string, lines: OrderLine[]): Promise<string> {
    if (lines.length === 0) {
      throw new Error("order must contain at least one line");
    }
    const ref = this.newRef();
    const reservationIds: string[] = [];

    try {
      for (const line of lines) {
        const res: ReserveResult = await this.inventory.reserve(line.sku, line.quantity, ref);
        if (res.status === "insufficient") {
          throw new InsufficientStockError(res.sku, res.available);
        }
        const reserved = res as Extract<ReserveResult, { status: "reserved" }>;
        reservationIds.push(reserved.reservationId);
      }

      const totalCents = lines.reduce((sum, l) => sum + l.quantity * l.unitPriceCents, 0);
      await this.orders.insert({ ref, customerId, lines, reservationIds, totalCents });
      return ref;
    } catch (err) {
      await this.releaseAll(reservationIds);
      throw err;
    }
  }

  private async releaseAll(ids: string[]): Promise<void> {
    for (const id of ids) {
      try {
        await this.inventory.release(id);
      } catch (releaseErr) {
        console.error(JSON.stringify({ msg: "release failed", reservationId: id, error: String(releaseErr) }));
      }
    }
  }
}

import { Pool } from "pg";
import { InventoryStore, ReserveResult } from "./inventory";

export class PgInventoryStore implements InventoryStore {
  constructor(private readonly pool: Pool) {}

  async reserve(sku: string, quantity: number, orderRef: string): Promise<ReserveResult> {
    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");
      const row = await client.query(
        "SELECT on_hand - reserved AS available FROM stock WHERE sku = $1 FOR UPDATE",
        [sku],
      );
      if (row.rowCount === 0) {
        await client.query("ROLLBACK");
        return { status: "unknown_sku", sku };
      }
      const available = Number(row.rows[0].available);
      if (available < quantity) {
        await client.query("ROLLBACK");
        return { status: "insufficient", sku, available };
      }
      await client.query("UPDATE stock SET reserved = reserved + $2 WHERE sku = $1", [sku, quantity]);
      const ins = await client.query(
        "INSERT INTO reservations (sku, quantity, order_ref) VALUES ($1, $2, $3) RETURNING id",
        [sku, quantity, orderRef],
      );
      await client.query("COMMIT");
      return { status: "reserved", reservationId: String(ins.rows[0].id), sku, quantity };
    } catch (err) {
      await client.query("ROLLBACK").catch(() => undefined);
      throw err;
    } finally {
      client.release();
    }
  }

  async release(reservationId: string): Promise<void> {
    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");
      const del = await client.query(
        "DELETE FROM reservations WHERE id = $1 RETURNING sku, quantity",
        [reservationId],
      );
      if (del.rowCount === 1) {
        const { sku, quantity } = del.rows[0];
        await client.query("UPDATE stock SET reserved = reserved - $2 WHERE sku = $1", [sku, quantity]);
      }
      await client.query("COMMIT");
    } catch (err) {
      await client.query("ROLLBACK").catch(() => undefined);
      throw err;
    } finally {
      client.release();
    }
  }
}
